export const getRemoveProductUrl = (id: number,
    productId: number,) => {




  return `/api/group-purchases/individual/${id}/products/${productId}`
}

export const removeProduct = async (id: number,
    productId: number, options?: Parameters<typeof http>[1]): Promise<RsDataVoid> => {

  return http<RsDataVoid>(getRemoveProductUrl(id,productId),
  {
    ...options,
    method: 'DELETE'


  }
);}





export const getRemoveProductMutationKey = () => ['removeProduct'] as const;

export const getRemoveProductMutationOptions = <TError = unknown,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof removeProduct>>, TError,RemoveProductMutationVariables, TContext>, request?: SecondParameter<typeof http>}
): UseMutationOptions<Awaited<ReturnType<typeof removeProduct>>, TError,RemoveProductMutationVariables, TContext> => {

const mutationKey = getRemoveProductMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof removeProduct>>, RemoveProductMutationVariables> = (props) => {
          const {id,productId} = props ?? {};

          return  removeProduct(id,productId,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RemoveProductMutationResult = NonNullable<Awaited<ReturnType<typeof removeProduct>>>

    export type RemoveProductMutationError = unknown
    export type RemoveProductMutationVariables = {id: number;productId: number}

    export const useRemoveProduct = <TError = unknown,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof removeProduct>>, TError,RemoveProductMutationVariables, TContext>, request?: SecondParameter<typeof http>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof removeProduct>>,
        TError,
        RemoveProductMutationVariables,
        TContext
      > => {
      return useMutation(getRemoveProductMutationOptions(options), queryClient);
    }
